"""Short-code generation and validation helpers.

Codes are drawn from the base62 alphabet with a CSPRNG (``secrets``); the ``random``
module is deliberately never used so codes stay unguessable.
"""

import re
import secrets
import string

ALPHABET = string.ascii_letters + string.digits

RESERVED_CODES = frozenset(
    {"healthz", "readyz", "api", "docs", "redoc", "openapi.json", "static", "favicon.ico"}
)

CODE_PATTERN = re.compile(r"^[A-Za-z0-9]{1,32}$")


def generate_code(length: int) -> str:
    """Return a random base62 code of ``length`` characters."""
    return "".join(secrets.choice(ALPHABET) for _ in range(length))


def is_reserved(code: str) -> bool:
    """Return True if ``code`` collides (case-insensitively) with a reserved path segment."""
    return code.casefold() in RESERVED_CODES


def is_valid_code_format(code: str) -> bool:
    """Return True if ``code`` could be a stored short code (1-32 base62 characters)."""
    return bool(CODE_PATTERN.fullmatch(code))

"""Small helpers shared by the test modules (no fixtures here)."""

from __future__ import annotations

from sqlalchemy import func, select

TEST_BASE_URL = "http://sho.rt"
TEST_API_KEY = "test-api-key-0123456789abcdef"
AUTH_HEADERS = {"X-API-Key": TEST_API_KEY}


def new_session(client):
    """Open an ORM session against the client's (temporary) database."""
    return client.app.state.session_factory()


def count_rows(client, model) -> int:
    with new_session(client) as s:
        return int(s.scalar(select(func.count()).select_from(model)))


def create_link(client, url: str = "https://example.com/a?b=1", **kwargs) -> dict:
    resp = client.post("/api/links", json={"url": url}, **kwargs)
    assert resp.status_code == 201, resp.text
    return resp.json()


def assert_json_error(resp, status: int) -> None:
    assert resp.status_code == status, resp.text
    assert resp.headers["content-type"].startswith("application/json")
    assert "detail" in resp.json()

"""Declarative base and shared helpers for the ORM layer."""

from datetime import UTC, datetime

from sqlalchemy.orm import DeclarativeBase


class Base(DeclarativeBase):
    """Declarative base class for all ORM models."""


def utcnow() -> datetime:
    """Return the current UTC time as a naive datetime (portable across databases)."""
    return datetime.now(UTC).replace(tzinfo=None)
